import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/collaborate/templates-gallery.png",l="/docs/images/collaborate/templates-publish.png",g=JSON.parse('{"title":"Use and publish templates","description":"Start a new document from a template, publish your own document as a template, and submit it to the public gallery.","frontmatter":{"title":"Use and publish templates","description":"Start a new document from a template, publish your own document as a template, and submit it to the public gallery.","type":"how-to"},"headers":[],"relativePath":"collaborate/templates.md","filePath":"collaborate/templates.md"}'),n={name:"collaborate/templates.md"};function i(p,e,h,c,d,m){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="use-and-publish-templates" tabindex="-1">Use and publish templates <a class="header-anchor" href="#use-and-publish-templates" aria-label="Permalink to &quot;Use and publish templates&quot;">​</a></h1><p>A template is a document that others can copy to start their own, without ever changing the original.</p><p>Any document type can be a template. Using one gives you a new document in your workspace with the template&#39;s content.</p><h2 id="browse-templates" tabindex="-1">Browse templates <a class="header-anchor" href="#browse-templates" aria-label="Permalink to &quot;Browse templates&quot;">​</a></h2><p>Open the gallery in one of three ways:</p><ul><li>In the sidebar, click <strong>Templates</strong>. The <strong>This workspace</strong> tab lists templates published in your workspace, and <strong>Public gallery</strong> lists public ones.</li><li>Go to <code>/templates</code> to see the public gallery. You don&#39;t need to be signed in.</li><li>On the documents list, click <strong>New</strong> &gt; <strong>New from template</strong>.</li></ul><p>Each gallery has <strong>Search templates</strong>, filters for document type and category, and a sort menu with <strong>Most used</strong> and <strong>Newest</strong>. Click <strong>Load more</strong> at the bottom for more results.</p><p><img src="'+s+'" alt="Workspace Templates page on the This workspace tab with search, filters, and three template cards"></p><h2 id="start-a-document-from-a-template" tabindex="-1">Start a document from a template <a class="header-anchor" href="#start-a-document-from-a-template" aria-label="Permalink to &quot;Start a document from a template&quot;">​</a></h2><ol><li>On the documents list, open the folder you want the document in.</li><li>Click <strong>New</strong> &gt; <strong>New from template</strong>.</li><li>Choose <strong>This workspace</strong> or <strong>Public gallery</strong>.</li><li>Click <strong>Use</strong> on a template.</li></ol><p>The new document opens. It&#39;s named after the template and is in the current workspace and folder. An empty board also has a <strong>Start from a template</strong> link that opens the board templates.</p><h3 id="use-a-template-from-its-page" tabindex="-1">Use a template from its page <a class="header-anchor" href="#use-a-template-from-its-page" aria-label="Permalink to &quot;Use a template from its page&quot;">​</a></h3><ol><li>Open a template link, or click <strong>Open</strong> on a card in the sidebar&#39;s <strong>Templates</strong> page.</li><li>To look inside first, click <strong>Preview</strong>.</li><li>Under <strong>Workspace</strong>, choose where the new document goes.</li><li>Click <strong>Use this template</strong>.</li></ol><p>If you aren&#39;t signed in, the button says <strong>Sign in to use this template</strong> and brings you back afterward.</p><p>You get your own document, with you as its author. If the workspace already has a document with that name, a number such as <code>(2)</code> is added. Comments, share links, and version history aren&#39;t copied.</p><h2 id="publish-a-document-as-a-template" tabindex="-1">Publish a document as a template <a class="header-anchor" href="#publish-a-document-as-a-template" aria-label="Permalink to &quot;Publish a document as a template&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need to be the document&#39;s author or a workspace owner.</li><li>A sheet with a database or lakehouse tab can&#39;t be published.</li></ul></div><ol><li>Open the document and click <strong>Share</strong> in the header.</li><li>In the <strong>Template</strong> section, enter a <strong>Description</strong>, for example <em>Monthly budget with a summary tab</em>.</li><li>Choose <strong>Listed in this workspace</strong> or <strong>Anyone with the link</strong>.</li><li>Click <strong>Publish as template</strong>.</li></ol><p>The template link is copied to your clipboard. The card uses the document&#39;s title and a picture of the document as it looks now.</p><p><img src="'+l+'" alt="Share dialog Template section with a Description, the visibility menu, and Publish as template"></p><h2 id="edit-a-template-s-card" tabindex="-1">Edit a template&#39;s card <a class="header-anchor" href="#edit-a-template-s-card" aria-label="Permalink to &quot;Edit a template&#39;s card&quot;">​</a></h2><ol><li>Open the document and click <strong>Share</strong>.</li><li>In the <strong>Template</strong> section, change <strong>Description</strong>, <strong>Visibility</strong>, <strong>Category</strong>, or <strong>Tags</strong> (separated by commas, up to 10).</li><li>Click <strong>Save</strong>.</li></ol><p>The picture doesn&#39;t update as you edit the document. To refresh it, click <strong>Update preview</strong>.</p><p>Others in the workspace see the template&#39;s name, how many times it was used, and a copy button, but can&#39;t change it.</p><h2 id="unpublish-a-template" tabindex="-1">Unpublish a template <a class="header-anchor" href="#unpublish-a-template" aria-label="Permalink to &quot;Unpublish a template&quot;">​</a></h2><ol><li>Open the document and click <strong>Share</strong>.</li><li>In the <strong>Template</strong> section, click the trash icon (<strong>Unpublish template</strong>).</li></ol><p>The card and its link stop working. Your document isn&#39;t changed, and documents people already made from it are theirs to keep.</p><h2 id="choose-who-can-find-a-template" tabindex="-1">Choose who can find a template <a class="header-anchor" href="#choose-who-can-find-a-template" aria-label="Permalink to &quot;Choose who can find a template&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Visibility</th><th>Who can find and use it</th></tr></thead><tbody><tr><td><strong>Anyone with the link</strong></td><td>Only people you send the link to. It isn&#39;t listed anywhere.</td></tr><tr><td><strong>This workspace</strong></td><td>Every member, on the workspace&#39;s <strong>Templates</strong> page, plus anyone with the link.</td></tr><tr><td>Public</td><td>Everyone, in the public gallery. Only a reviewer can make a template public.</td></tr></tbody></table><p>If someone opens a template they&#39;re not allowed to see, they get <strong>Template not found</strong>, the same as for a link that doesn&#39;t exist.</p><h2 id="submit-a-template-to-the-public-gallery" tabindex="-1">Submit a template to the public gallery <a class="header-anchor" href="#submit-a-template-to-the-public-gallery" aria-label="Permalink to &quot;Submit a template to the public gallery&quot;">​</a></h2><ol><li>Publish the document as a template first.</li><li>In the Share dialog&#39;s <strong>Template</strong> section, under <strong>Public gallery</strong>, click <strong>Submit for review</strong>.</li></ol><p>Your username and profile picture will appear on the card, and you allow anyone to copy and change the content. Until a reviewer decides, your template keeps working as before, and you can&#39;t change its title, description, category, or picture.</p><p>The <strong>Template</strong> section shows the result, with any note from the reviewer, and you get a notification:</p><ul><li><strong>Approved</strong>: the template appears in the public gallery.</li><li><strong>Not accepted into the public gallery</strong>: it keeps its earlier visibility. Fix what the note says and click <strong>Submit again</strong>.</li><li><strong>Removed from the gallery by a reviewer</strong>: the template stops working for everyone else and can&#39;t be edited, resubmitted, or unpublished. Your document isn&#39;t affected.</li></ul><p>Editing a public template&#39;s document, or its title, description, category, or picture, sends it back for review.</p><p>Public templates need template review set up on your deployment. If it isn&#39;t, <strong>Submit for review</strong> shows an error. See <a href="/docs/developers/self-hosting/optional-features.html">Optional features</a> if you run your own server.</p><h2 id="report-a-public-template" tabindex="-1">Report a public template <a class="header-anchor" href="#report-a-public-template" aria-label="Permalink to &quot;Report a public template&quot;">​</a></h2><ol><li>Open the template&#39;s page while signed in.</li><li>Select a reason from <strong>Report this template</strong>.</li><li>Click <strong>Send report</strong>.</li></ol><p>A reviewer looks at the report. Reporting doesn&#39;t hide the template.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/collaborate/share.html">Share a document</a> to give access to the original instead of a copy.</li><li><a href="/docs/collaborate/folders.html">Folders</a> to choose where new documents land.</li><li><a href="/docs/board/run-a-retro.html">Run a retro</a> to try a board template.</li></ul>',42)])])}const b=t(n,[["render",i]]);export{g as __pageData,b as default};
